def _backfill():
    """Record owners for files uploaded before this table existed, so they stay reachable for the right workspace.
    Website images become public; everything else is private."""
    import json
    from pathlib import Path

    bind = op.get_bind()
    spec = json.loads((Path(__file__).resolve().parents[2] / "app" / "modules.json").read_text())
    rows = {}

    def add(url, org, public):
        if isinstance(url, str) and url.startswith("/files/"):
            name = url[len("/files/"):][:64]
            prev = rows.get(name)
            rows[name] = (org, public or bool(prev and prev[1]))

    for url, org in bind.execute(sa.text(
            "SELECT e.file_url, p.organization_id FROM evidence e JOIN activities a ON a.id = e.activity_id "
            "JOIN commitments c ON c.id = a.commitment_id JOIN projects p ON p.id = c.project_id WHERE e.file_url IS NOT NULL")):
        add(url, org, False)
    for m in spec["modules"]:
        cols = [f["key"] for f in m["fields"] if f["type"] == "file"]
        table = f"m_{m['key']}"
        if not cols or not bind.execute(sa.text("SELECT to_regclass(:t)"), {"t": table}).scalar():
            continue
        for col in cols:
            sql = f'SELECT "{col}", organization_id FROM "{table}" WHERE "{col}" IS NOT NULL'  # nosec B608 - identifiers come from the bundled module spec
            for val, org in bind.execute(sa.text(sql)):
                v = val if isinstance(val, dict) else json.loads(val) if isinstance(val, str) else {}
                add(v.get("url"), org, m["app"] == "website")
    for data, org in bind.execute(sa.text("SELECT data, organization_id FROM form_submissions")):
        d = data if isinstance(data, dict) else json.loads(data)
        for v in d.values():
            if isinstance(v, dict):
                add(v.get("url"), org, False)
    for name, (org, public) in rows.items():
        bind.execute(sa.text("INSERT INTO files (name, organization_id, public, size, created_at) VALUES (:n, :o, :p, 0, now()) ON CONFLICT (name) DO NOTHING"),
                     {"n": name, "o": org, "p": public})
